INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-atrium-dextrum','organ-heart','Atrium_Dextrum','الأذين الأيمن','Right Atrium','Atrium cordis dextrum','TA2-3955','Cardiac Chamber','يستقبل الدم الوريدي غير المؤكسج من الوريدين الأجوفين العلوي والسفلي والجيب التاجي ويدفعه عبر الصمام ثلاثي الشرف إلى البطين الأيمن.','Receives deoxygenated venous blood from the superior/inferior venae cavae and coronary sinus, delivering it across the tricuspid valve.','يضم العقدة الجيبية الأذينية (SA Node)؛ يؤدي توسعه إلى زيادة قابلية الرجفان الأذيني.','Houses the sinoatrial pacemaker node; right atrial enlargement predisposes to atrial arrhythmias.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-atrium-sinistrum','organ-heart','Atrium_Sinistrum','الأذين الأيسر','Left Atrium','Atrium cordis sinistrum','TA2-3996','Cardiac Chamber','يستقبل الدم المؤكسج العائد من الرئتين عبر الأوردة الرئوية الأربعة ويمرره عبر الصمام التاجي إلى البطين الأيسر.','Receives oxygenated blood from the four pulmonary veins and channels it through the mitral valve into the left ventricle.','بؤرة انطلاق شائعة للرجفان الأذيني عند فوهات الأوردة الرئوية وموضع تشكل الخثرات في لويحقة الأذين الأيسر.','Pulmonary vein ostia are primary triggers for atrial fibrillation; the left atrial appendage is a major thromboembolic site.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-ventriculus-dexter','organ-heart','Ventriculus_Dexter','البطين الأيمن','Right Ventricle','Ventriculus cordis dexter','TA2-3973','Cardiac Chamber','يضخ الدم غير المؤكسج عبر الصمام الرئوي إلى الجذع الرئوي تحت ضغط منخفض نسبياً (~25/8 مم زئبق) لحماية الشعيرات السنخية.','Pumps deoxygenated blood across the pulmonary valve into the pulmonary trunk at low pressure (~25/8 mmHg) to preserve alveolar capillaries.','يتأثر بارتفاع التوتر الرئوي والانصمام الرئوي وفشل القلب الأيمن (Cor pulmonale).','Susceptible to pressure overload in pulmonary hypertension, pulmonary embolism, and cor pulmonale.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-ventriculus-sinister','organ-heart','Ventriculus_Sinister','البطين الأيسر','Left Ventricle','Ventriculus cordis sinister','TA2-4005','Cardiac Chamber','المضخة العضلية الرئيسية للدورة الجهازية؛ يدفع الدم المؤكسج عبر الصمام الأبهري لتروية الدماغ والكليتين وعضلة القلب نفسها.','Primary muscular pump of systemic circulation ejecting oxygenated blood across the aortic valve (~120/80 mmHg).','يتضخم في فرط ضغط الدم الشرياني المزمن (LVH) ويضعف كسر قذفه (EF) في قصور القلب الانقباضي واحتشاء عضلة القلب.','Undergoes concentric hypertrophy in chronic hypertension and reduced ejection fraction in systolic heart failure.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-arcus-aortae','organ-heart','Arcus_Aortae','قوس الأبهر','Aortic Arch','Arcus aortae','TA2-4116','Great Vessel','الوعاء الشرياني المرن الأكبر الذي يوزع الدم المؤكسج من البطين الأيسر ويضم مستقبلات الضغط (Baroreceptors) لضبط المنعكس الوعائي.','Main elastic arterial conduit distributing left ventricular output and housing high-pressure arterial baroreceptors.','تصلب جداره يزيد ضغط النبض الانقباضي والحمل البعدي على البطين الأيسر.','Arterial stiffening elevates systolic pulse pressure and left ventricular afterload.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-nodus-sinuatrialis','organ-heart','Nodus_Sinuatrialis','العقدة الجيبية الأذينية (الناظم الطبيعي)','Sinoatrial (SA) Node','Nodus sinuatrialis','TA2-4041','Conduction Tissue','ناظم الخطى الطبيعي للقلب (60-100 نبضة/دقيقة) في جدار الأذين الأيمن قرب مصب الوريد الأجوف العلوي.','Intrinsic cardiac pacemaker (60-100 bpm) located in the superior right atrial wall near the crista terminalis.','تخضع لتأثير مستقبلات بيتا-1 الودية (تسرع) ومستقبلات M2 المسكارينية للعصب المبهم (تباطؤ).','Modulated by sympathetic beta-1 adrenergic acceleration and vagal M2 muscarinic deceleration.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-heart-macro','organ-heart','MACRO_ANATOMY','التشريح العياني والحجرات الأربع والصمامات','Macroscopic Anatomy, Four Chambers & Valves','يتألف القلب (Cor) من أذينين علويين يستقبلان الدم العائد وبطينين سفليين يضخانه. يفصل الصمام ثلاثي الشرف (Valva atrioventricularis dextra) بين الأذين والبطين الأيمن، بينما يفصل الصمام التاجي/الميترالي (Valva mitralis) بين الأذين والبطين الأيسر. يتميز جدار البطين الأيسر بسماكة عضلية تبلغ نحو 3 أضعاف البطين الأيمن لمواجهة المقاومة الوعائية الجهازية.','The heart (Cor) consists of two receiving atria and two pumping ventricles separated by the tricuspid and mitral valves. The left ventricular myocardium is ~3x thicker than the right to overcome systemic vascular resistance.',1) ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-heart-histology','organ-heart','HISTOLOGY_LAYERS','الطبقات النسيجية الثلاث وجهاز التوصيل الكهربائي','Three Histological Layers & Electrical Conduction System','يتكون جدار القلب من الشغاف الداخلي المبطن (Endocardium)، وعضلة القلب المخططة اللاإرادية المترابطة بالأقراص البينية (Myocardium)، والنخاب المصلي الخارجي (Epicardium). ينشأ جهد الفعل التلقائي في العقدة الجيبية الأذينية (SA Node) وينتقل إلى العقدة الأذينية البطينية (AV Node) ثم حزمة هيس وألياف بوركينجي.','The cardiac wall comprises the endocardium, striated myocardium linked by intercalated discs, and visceral epicardium. Impulse generation begins in the sinoatrial (SA) node, delays at the AV node, and propagates rapidly via the His-Purkinje network.',2) ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-heart-physiology','organ-heart','PHYSIOLOGY_HOMEOSTASIS','الوظيفة الفسيولوجية ومعادلة النتاج القلبي','Physiological Function & Cardiac Output Homeostasis','يُحسب النتاج القلبي (CO = HR × SV) بحاصل ضرب سرعة القلب في حجم الضربة، ويتحدد حجم الضربة بثلاثة عوامل رئيسية: الحمل القبلي (Preload وفق قانون فرانك-ستارلينغ)، والحمل البعدي (Afterload)، والقلوصية العضلية (Contractility/Inotropy).','Cardiac Output (CO = HR × SV) is governed by heart rate and stroke volume, where stroke volume depends on preload (Frank-Starling mechanism), afterload, and myocardial contractility.',3) ON CONFLICT DO NOTHING;
INSERT INTO science_figures (id,organ_id,title_ar,title_en,provenance_type,license,attribution,annotations_json) VALUES ('fig-cor-conduction-v1','organ-heart','مخطط تشريحي موثق: الحجرات الأربع ومسار التوصيل الكهربائي للقلب (Cor)','Verified Anatomical Diagram: Four Chambers & Conduction Pathway of the Heart (Cor)','SCHEMATIC_EDUCATIONAL','CC-BY-4.0 (Dawa & Hayah Vector Diagram based on TA2 & OpenStax)','دواء وحياة — وفق معيار FIPAT TA2 و OpenStax Anatomy & Physiology 2e','[{"markerNumber": 1, "labelAr": "العقدة الجيبية الأذينية", "labelEn": "Sinoatrial Node", "labelLatin": "Nodus sinuatrialis", "descriptionAr": "بداية الشرارة الكهربائية التلقائية في سقف الأذين الأيمن.", "descriptionEn": "Primary pacemaker initiating spontaneous depolarization in the right atrium."}, {"markerNumber": 2, "labelAr": "العقدة الأذينية البطينية", "labelEn": "Atrioventricular Node", "labelLatin": "Nodus atrioventricularis", "descriptionAr": "تؤخر النبضة ~0.1 ثانية لإتمام امتلاء البطينين قبل انقباضهما.", "descriptionEn": "Delays impulse ~100 ms to allow complete ventricular diastolic filling."}, {"markerNumber": 3, "labelAr": "حزمة هيس وألياف بوركينجي", "labelEn": "His Bundle & Purkinje Fibers", "labelLatin": "Fasciculus atrioventricularis", "descriptionAr": "تنقل التنبيه بسرعة فائقة إلى عضلة البطينين الأيمن والأيسر.", "descriptionEn": "Rapidly conducts excitation throughout right and left ventricular myocardium."}]') ON CONFLICT DO NOTHING;
