INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-tunica-intima','organ-blood-vessels',NULL,'البطانة الوعائية (الغلالة الباطنة)','Vascular Endothelium (Tunica Intima)','Tunica intima vasorum','TA2-3891','Histological Layer','تفرز أكسيد النيتريك الموسع للأوعية والبروستاسيكلين المانع لتكدس الصفائح.','Secretes vasodilatory nitric oxide (NO) and anti-aggregatory prostacyclin.','يمثل الخلل البطاني (Endothelial Dysfunction) الخطوة الأولى في تصلب الشرايين وفرط ضغط الدم.','Endothelial dysfunction initiates atherogenesis and impairs vasodilation in hypertension.','src-openstax-anatomy-v2') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-vessels-layers','organ-blood-vessels','HISTOLOGY_LAYERS','الغلالات الثلاث لجدار الوعاء الدموي والبطانة الوعائية','Three Tunics of the Vascular Wall & Endothelium','يتكون جدار الشرايين والأوردة من الغلالة الباطنة (Tunica intima) المبطنة بالخلايا البطانية المفرزة لأكسيد النيتريك (NO)، والغلالة الوسطى العضلية الملساء (Tunica media) التي تحدد قطر الشرينات ومقاومتها، والغلالة البرانية الضامة (Tunica externa/adventitia).','Vessel walls comprise the nitric-oxide-producing tunica intima, smooth-muscle tunica media controlling arteriolar tone, and collagenous tunica adventitia.',1) ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('stage02-organ-blood-vessels-src-ta2-fipat','organ-blood-vessels','ORGAN','src-ta2-fipat','2026-10-24',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('stage02-organ-blood-vessels-src-openstax-anatomy-v2','organ-blood-vessels','ORGAN','src-openstax-anatomy-v2','2026-10-24',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-alveoli-pulmonis','organ-lungs','Alveoli_Pulmonis','الأسناخ الرئوية والحاجز السنخي الشعري','Pulmonary Alveoli & Blood-Air Barrier','Alveoli pulmonis','TA2-3245','Micro-Anatomical Unit','الوحدة الوظيفية لتبادل الغازات وإفراز السورفاكتانت عبر الخلايا السنخية من النمط الثاني.','Functional gas-exchange unit where Type II pneumocytes secrete surfactant.','تدمير جدرانها يسبب النفاخ الرئوي (Emphysema)، وامتلاؤها بالنضح الالتهابي يسبب ذات الرئة (Pneumonia).','Septal destruction causes emphysema; inflammatory exudate consolidation causes pneumonia.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-lungs-anatomy','organ-lungs','MACRO_ANATOMY','الفصوص الرئوية والتفرع القصبي حتى الأسناخ','Pulmonary Lobes & Bronchial Branching to Alveoli','تتكون الرئة اليمنى (Pulmo dexter) من ثلاثة فصوص (علوي وأوسط وسفلي)، بينما تتكون الرئة اليسرى (Pulmo sinister) من فصين لوجود الثلمة القلبية. تتفرع الرغامى إلى قصبتين رئيسيتين ثم فصية وقطعية وقصيبات انتهائية وتنفسية تنتهي بالأسناخ الرئوية.','The right lung has three lobes and the left lung has two lobes accommodating the cardiac notch. Conducting airways branch across ~23 generations into respiratory bronchioles and alveolar sacs.',1) ON CONFLICT DO NOTHING;
INSERT INTO science_figures (id,organ_id,title_ar,title_en,provenance_type,license,attribution,annotations_json) VALUES ('fig-lungs-alveoli-v1','organ-lungs','مخطط تشريحي موثق: الشجرة القصبية والوحدة السنخية الشعرية','Verified Diagram: Bronchial Tree & Alveolar-Capillary Unit','SCHEMATIC_EDUCATIONAL','CC-BY-4.0 (Dawa & Hayah Educational Diagram based on OpenStax)','دواء وحياة — وفق معيار TA2 و OpenStax','[{"markerNumber": 1, "labelAr": "الرغامى والقصبتان الرئيسيتان", "labelEn": "Trachea & Main Bronchi", "labelLatin": "Trachea et Bronchi principales", "descriptionAr": "مدعومة بحلقات غضروفية زجاجية لمنع الانخماص.", "descriptionEn": "Supported by hyaline cartilage rings preventing airway collapse."}, {"markerNumber": 2, "labelAr": "القصيبات التنفسية والعضلات الملساء", "labelEn": "Respiratory Bronchioles & Smooth Muscle", "labelLatin": "Bronchioli respiratorii", "descriptionAr": "غنية بمستقبلات بيتا-2 الودية ومستقبلات M3 المسكارينية.", "descriptionEn": "Rich in beta-2 adrenergic (bronchodilation) and M3 muscarinic (bronchoconstriction) receptors."}]') ON CONFLICT DO NOTHING;
