INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-glomerulus-renalis','organ-kidneys','Cortex_Renalis','الكبيبة الكلوية وحاجز الترشيح','Renal Glomerulus & Filtration Barrier','Glomerulus renalis (Corpusculum renale)','TA2-3362','Micro-Anatomical Unit','ترشيح نحو 180 لتراً من البلازما يومياً (GFR ~ 90-120 mL/min) مع منع عبور الألبومين وخلايا الدم.','Filters ~180 L/day of plasma (GFR ~90-120 mL/min) while retaining albumin and cellular elements.','يتحكم الشرين الوارد (بوساطة البروستاغلاندينات) والشرين الصادر (بوساطة أنجيوتنسين II) في الضغط الكبيبي.','Afferent arteriolar tone (prostaglandin-dependent) and efferent tone (Angiotensin II-dependent) govern intraglomerular pressure.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-kidney-nephron','organ-kidneys','HISTOLOGY_LAYERS','تشريح النفرون ومواضع عمل المدرات الدوائية','Nephron Segmental Anatomy & Diuretic Target Sites','يتكون النفرون من الكبيبة الكلوية (Glomerulus) ومحفظة بومان، يتبعها الأنبوب القريب (حيث تعمل مثبطات SGLT2 والأنهيدراز الكربوني)، ثم عروة هنلي الصاعدة السميكة (موضع مثبطات ناقل Na-K-2Cl مثل الفوروسيميد)، ثم الأنبوب البعيد (موضع الثيازيدات)، والقناة الجامعة (موضع مضادات الألدوستيرون والهرمون المضاد للإدرار ADH).','The nephron comprises Bowman capsule and glomerulus, proximal convoluted tubule (SGLT2/CA inhibitor site), thick ascending loop of Henle (NKCC2 loop diuretic site), distal convoluted tubule (NCC thiazide site), and collecting duct (ENaC/aldosterone site).',1) ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('stage02-organ-kidneys-src-ta2-fipat','organ-kidneys','ORGAN','src-ta2-fipat','2026-10-24',NULL,'under_review') ON CONFLICT DO NOTHING;
