INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-vena-portae','organ-liver',NULL,'الوريد البابي الكبدي والثلاثية البابية','Hepatic Portal Vein & Portal Triad','Vena portae hepatis','TA2-4842','Vascular Conduit','ينقل ~75% من التروية الدموية الكبدية المحملة بالمغذيات والأدوية الممتصة من القناة الهضمية.','Delivers ~75% of hepatic blood flow carrying absorbed nutrients and orally administered drugs.','مسؤول عن ظاهرة المرور الكبدي الأول (First-Pass Effect) التي تقلل التوافر الحيوي الفموي لبعض الأدوية.','Mediates hepatic first-pass extraction determining oral bioavailability.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-liver-lobule','organ-liver','HISTOLOGY_LAYERS','الفصيص الكبدي والثلاثية البابية واستقلاب الدواء','Hepatic Lobule, Portal Triad & Drug Biotransformation','تنتظم الخلايا الكبدية (Hepatocytes) حول الوريد المركزي وتستقبل الدم من الجيبانيات الكبدية المغذاة بالثلاثية البابية (فرع الوريد البابي، فرع الشريان الكبدي، والقناة الصفراوية). تحول تفاعلات الطور الأول (CYP3A4, CYP2D6, CYP2C9) وتفاعلات الاقتران في الطور الثاني (UGT) المركبات المحبة للدهون إلى مستقلبات قطبية قابلة للإطراح.','Hepatocytes arranged around central veins receive sinusoidal blood from portal triads and execute Phase I (CYP3A4, CYP2D6, CYP2C9) oxidation and Phase II glucuronidation/sulfation.',1) ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('stage02-organ-liver-src-ta2-fipat','organ-liver','ORGAN','src-ta2-fipat','2026-10-24',NULL,'under_review') ON CONFLICT DO NOTHING;
