INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('stage02-organ-stomach-duodenum-src-openstax-anatomy-v2','organ-stomach-duodenum','ORGAN','src-openstax-anatomy-v2','2026-10-24',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO anatomical_structures (id,organ_id,mesh_node_name,name_ar,name_en,latin_name,ta2_code,structure_type,function_ar,function_en,clinical_relevance_ar,clinical_relevance_en,source_id) VALUES ('struct-circulus-arteriosus-cerebri','organ-brain',NULL,'حلقة ويليس الشريانية الدماغية','Cerebral Arterial Circle (Circle of Willis)','Circulus arteriosus cerebri','TA2-4510','Arterial Anastomosis','تفاغر شرياني في قاعدة الدماغ يربط التروية السباتية الأمامية بالتروية الفقارية القاعدية الخلفية.','Basal cerebral arterial anastomosis linking anterior carotid and posterior vertebrobasilar circulations.','انسداد فروعها (مثل الشريان المخي الأوسط MCA) يسبب السكتة الدماغية الإقفارية الحادة.','Occlusion of its major branches (e.g., middle cerebral artery) causes acute ischemic stroke.','src-ta2-fipat') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-brain-bbb','organ-brain','PHYSIOLOGY_HOMEOSTASIS','الحاجز الدموي الدماغي (BBB) وانتقائية عبور الدواء','Blood-Brain Barrier (BBB) & Neuropharmacological Selectivity','يتشكل الحاجز الدموي الدماغي من الخلايا البطانية الشعرية المتصلة بوصلات محكمة (Tight Junctions) وأقدام الخلايا النجمية (Astrocytic Endfeet). تعبر الجزيئات الصغيرة المحبة للدهون بسهولة، بينما تُطرد العديد من المركبات القطبية بواسطة مضخة P-glycoprotein (ABCB1).','Formed by continuous capillary endothelium with tight junctions and astrocytic endfeet, the BBB restricts polar solutes while P-glycoprotein actively extrudes xenobiotics.',1) ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('stage02-organ-brain-src-ta2-fipat','organ-brain','ORGAN','src-ta2-fipat','2026-10-24',NULL,'under_review') ON CONFLICT DO NOTHING;
