INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-a_overview','dis-hypertension','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','زيادة مستدامة في ضغط الدم الشرياني في القياسات المتكررة، وتُعد عامل الخطورة القابل للتعديل الأول للسكتة الدماغية وقصور القلب والمرض الكلوي المزمن.','Persistent elevation of systemic arterial pressure across repeated measurements; the leading modifiable risk factor for stroke, heart failure, and CKD.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-b_epidemiology','dis-hypertension','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','يمثل النمط الأولي (Essential) نحو 90-95% من الحالات؛ تشمل عوامل الخطورة: الاستعداد الوراثي، فرط الصوديوم الغذائي، السمنة، قلة النشاط البدني، ومقاومة الأنسولين.','Primary hypertension accounts for 90-95% of cases; risk factors include polygenic predisposition, high dietary sodium, obesity, physical inactivity, and insulin resistance.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-c_pathophysiology','dis-hypertension','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','اختلال توازن البطانة الوعائية (نقص أكسيد النيتريك NO وزيادة الإندوثيلين)، مع فرط نشاط الجهاز الودي وزيادة إفراز الرينين والأنجيوتنسين II والألدوستيرون مما يرفع المقاومة الوعائية الجهازية (SVR = BP / CO) ويؤدي إلى تضخم البطين الأيسر التكيفي (Concentric LVH).','Endothelial nitric oxide deficiency, sympathetic overactivity, and inappropriate RAAS activation increase arteriolar tone (SVR) and renal sodium retention, inducing concentric left ventricular hypertrophy.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-d_symptoms_red_flags','dis-hypertension','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','غالباً صامت سريرياً («القاتل الصامت»). العلامات التحذيرية الطارئة (Red Flags) لنوبة فرط الضغط الخبيث: صداع شديد مفاجئ، تشوش الرؤية أو وذمة حليمة العصب البصري، ألم صدري خناقي، أو ضيق نفس حاد (وذمة رئوية).','Frequently asymptomatic. Hypertensive emergency Red Flags: acute neurological deficit, papilledema/visual loss, acute chest pain, or flash pulmonary edema.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-e_diagnosis_differential','dis-hypertension','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','قياس ضغط الدم المنهجي المتكرر أو مراقبة الضغط على مدار 24 ساعة (ABPM)، مع تقييم وظائف الكلية (Creatinine, eGFR, Urine ACR)، شوارد الدم، تخطيط القلب الكهربائي (ECG)، واستبعاد الأسباب الثانوية.','Confirmed via ambulatory/home blood pressure monitoring alongside baseline serum creatinine, eGFR, electrolytes, urinalysis, 12-lead ECG, and screening for secondary causes.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-f_non_pharmacological','dis-hypertension','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','تقليل مدخول الصوديوم الغذائي، اتباع نمط حمية DASH الغنية بالبوتاسيوم والخضروات، ممارسة النشاط الهوائي المنتظم، خفض الوزن، والامتناع عن التدخين.','Dietary sodium restriction, DASH dietary pattern, regular aerobic exercise, weight optimization, and smoking cessation.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-g_pharmacotherapy_classes','dis-hypertension','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية المعتمدة لدراسة آليات خفض الضغط: 1) مثبطات الإنزيم المحول للأنجيوتنسين (ACEIs) وحاصرات مستقبلات الأنجيوتنسين (ARBs)، 2) حاصرات قنوات الكالسيوم ثنائية الهيدروبيريدين (CCBs)، 3) المدرات الثيازيدية وشبيهة الثيازيد. [تنبيه سلامة: الجرعات الفردية والخطط العلاجية قيد المراجعة البشرية ولا تُصرف إلا بإشراف الطبيب].','Educational drug classes: 1) ACE Inhibitors & ARBs, 2) Dihydropyridine Calcium Channel Blockers, 3) Thiazide/Thiazide-like Diuretics. [Safety Notice: Individual clinical dosing regimens are omitted and require physician prescription].','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-h_complications_prognosis','dis-hypertension','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','إصابة الأعضاء الهدفية (Target-Organ Damage): تضخم البطين الأيسر وقصور القلب، السكتة الدماغية الإقفارية أو النزفية، اعتلال الكلية بفرط الضغط، واعتلال الشبكية.','Target-organ damage includes left ventricular hypertrophy, heart failure, ischemic/hemorrhagic stroke, hypertensive nephrosclerosis, and retinopathy.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-i_sources_and_provenance','dis-hypertension','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (BA00) · NICE NG136 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · تاريخ المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (BA00) · NICE NG136 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypertension-j_terminology_and_links','dis-hypertension','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','فرط ضغط الدم الشرياني (Arterial Hypertension) · المقاومة الوعائية الجهازية (Systemic Vascular Resistance) · تضخم البطين الأيسر (Left Ventricular Hypertrophy).','Arterial Hypertension · Systemic Vascular Resistance (SVR) · Renin-Angiotensin-Aldosterone System (RAAS).','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-a_overview','dis-heart-failure','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','متلازمة تنجم عن ضعف تقلص البطين الأيسر (HFrEF، كسر القذف ≤40%) أو ضعف ارتخائه ومطاوعته الانبساطية (HFpEF، كسر القذف ≥50%).','Syndrome classified into Heart Failure with Reduced Ejection Fraction (HFrEF, LVEF ≤40%) and Preserved Ejection Fraction (HFpEF, LVEF ≥50%).','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-b_epidemiology','dis-heart-failure','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','الأسباب الرئيسية: داء الشرايين التاجية واحتشاء عضلة القلب السابق، فرط ضغط الدم المزمن، اعتلالات عضلة القلب، وأمراض الصمامات القلبية.','Primary etiologies: ischemic heart disease, chronic hypertension, dilated/hypertrophic cardiomyopathies, and valvular heart disease.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-c_pathophysiology','dis-heart-failure','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','يؤدي هبوط النتاج القلبي إلى تنشيط تعويضي مزمن ومضر للجهاز الودي ومحور RAAS والببتيدات المدرة للصوديوم (BNP/NT-proBNP)، مما يسبب إعادة قولبة البطين (Ventricular Remodeling) واحتباس الصوديوم والماء وارتفاع الضغط الشعري الرئوي.','Reduced cardiac output triggers maladaptive neurohormonal activation (sympathetic nervous system and RAAS), promoting myocardial fibrosis, ventricular remodeling, and fluid retention.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-d_symptoms_red_flags','dis-heart-failure','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','زلة تنفسية جهدية، اضطجاعية (Orthopnea)، زلة ليلية انتيابية (PND)، وذمة محيطية في الطرفين السفليين. العلامات التحذيرية الطارئة (Red Flags): زلة تنفسية في الراحة، نقص أكسجة حاد، خراخر رئوية منتشرة، أو هبوط ضغط مع برودة الأطراف (صدمة قلبية).','Exertional dyspnea, orthopnea, paroxysmal nocturnal dyspnea, ankle edema. Red Flags: resting hypoxia, frothy sputum (acute pulmonary edema), or cardiogenic shock.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-e_diagnosis_differential','dis-heart-failure','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','تخطيط صدى القلب عبر الصدر (Echocardiography) لتقييم كسر القذف (LVEF) وحركة الجدران والصمامات، وقياس الببتيدات المدرة للصوديوم (BNP / NT-proBNP)، وتخطيط القلب الكهربائي وصورة الصدر.','Transthoracic echocardiography (LVEF, chamber dimensions, valve function), plasma BNP/NT-proBNP levels, 12-lead ECG, and chest radiography.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-f_non_pharmacological','dis-heart-failure','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','ضبط مدخول الصوديوم والسوائل، المتابعة اليومية للوزن لاكتشاف احتباس السوائل المبكر، والتأهيل القلبي المتدرج.','Sodium/fluid management, daily weight monitoring for early decompensation detection, and supervised cardiac rehabilitation.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-g_pharmacotherapy_classes','dis-heart-failure','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية (الأركان الأربعة لقصور القلب الانقباضي + مدرات الاحتقان): 1) مثبطات مستقبل الأنجيوتنسين-نيبريليسين (ARNI) أو ACEIs/ARBs، 2) حاصرات بيتا المعتمدة، 3) مضادات مستقبلات القشرانيات المعدنية (MRA)، 4) مثبطات SGLT2، 5) مدرات العروة لتخفيف الاحتقان.','Educational pharmacotherapy pillars: 1) ARNI or ACEI/ARB, 2) Evidence-based Beta-Blockers, 3) Mineralocorticoid Receptor Antagonists, 4) SGLT2 Inhibitors, plus Loop Diuretics for volume overload.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-h_complications_prognosis','dis-heart-failure','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','المتلازمة القلبية الكلوية (Cardiorenal Syndrome)، اللانظميات البطينية والأذينية، والاعتماد المتكرر على الاستشفاء.','Cardiorenal syndrome, atrial/ventricular arrhythmias, progressive pump failure, and recurrent hospitalizations.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-i_sources_and_provenance','dis-heart-failure','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (BD10) · NICE NG106 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (BD10) · NICE NG106 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-heart-failure-j_terminology_and_links','dis-heart-failure','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','قصور القلب (Heart Failure) · كسر القذف (Ejection Fraction) · إعادة القولبة البطينية (Ventricular Remodeling).','Heart Failure · Ejection Fraction (LVEF) · Neurohormonal Activation · Natriuretic Peptides.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-a_overview','dis-coronary-artery-disease','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','تضيق تدريجي أو انسداد حاد في الشرايين التاجية النخابية المغذية لعضلة القلب (Arteriae coronariae).','Progressive luminal narrowing or acute plaque disruption within the epicardial coronary arteries.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-b_epidemiology','dis-coronary-artery-disease','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','عوامل الخطورة: فرط شحميات الدم (ارتفاع LDL-C)، فرط ضغط الدم، السكري، التدخين، والتاريخ العائلي المبكر.','Risk factors: elevated LDL cholesterol, hypertension, diabetes mellitus, smoking, and premature family history.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-c_pathophysiology','dis-coronary-artery-disease','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','تراكم البروتينات الشحمية المؤكسدة (oxLDL) تحت البطانة التاجية وتشكيل اللويحة العصيدية الليفية؛ وعند تمزق الغطاء الليفي للويحة تتفعل الصفائح الدموية وشلال التخثر مسببة متلازمة إكليلية حادة (ACS).','Subendothelial retention of oxidized LDL forms fibroatheromatous plaques; fibrous cap rupture exposes thrombogenic core triggering platelet aggregation and acute coronary syndrome.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-d_symptoms_red_flags','dis-coronary-artery-disease','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','ألم أو ضغط صدري خلف القص يثار بالجهد ويزول بالراحة في الذبحة المستقرة. العلامات التحذيرية الطارئة (Red Flags): ألم صدري ضاغط يستمر >15-20 دقيقة في الراحة، ينتشر للفك أو الذراع الأيسر مع تعرق بارد وغثيان (اشتباه احتشاء عضلة القلب الحاد).','Exertional retrosternal pressure relieved by rest in stable angina. Red Flags: rest angina >15-20 min radiating to jaw/left arm with diaphoresis and dyspnea (suspected acute MI).','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-e_diagnosis_differential','dis-coronary-artery-disease','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','تخطيط القلب الكهربائي (ECG) بـ 12 اتجاهاً، التروبونين القلبي عالي الحساسية (hs-cTn)، اختبار الجهد، وتصوير الشرايين التاجية المقطعي أو القسطري.','12-lead ECG, serial high-sensitivity cardiac troponins (hs-cTn), stress imaging, and CT/invasive coronary angiography.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-f_non_pharmacological','dis-coronary-artery-disease','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','إيقاف التدخين فوراً، ضبط شحوم الدم والضغط والسكري، والالتزام بالنشاط البدني الهوائي المراقب.','Smoking cessation, lipid/glycemic/BP control, Mediterranean diet, and structured exercise.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-g_pharmacotherapy_classes','dis-coronary-artery-disease','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) مضادات تكدس الصفائح الدموية، 2) مثبطات تصنيع الكوليسترول (الستاتينات) لتثبيت اللويحة العصيدية، 3) حاصرات بيتا لخفض استهلاك الأكسجين القلبي، 4) النترات العضوية وحاصرات قنوات الكالسيوم لتوسيع الأوعية التاجية.','Educational drug classes: 1) Antiplatelet agents, 2) Statins (plaque stabilization & LDL lowering), 3) Beta-blockers (myocardial oxygen demand reduction), 4) Nitrates & CCBs.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-h_complications_prognosis','dis-coronary-artery-disease','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','احتشاء عضلة القلب (Myocardial Infarction)، قصور القلب الإقفاري، واللانظميات البطينية المهددة للحياة.','Myocardial infarction, ischemic cardiomyopathy, heart failure, and ventricular arrhythmias.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-i_sources_and_provenance','dis-coronary-artery-disease','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (BA80) · NICE CG126 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (BA80) · NICE CG126 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-coronary-artery-disease-j_terminology_and_links','dis-coronary-artery-disease','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','داء الشرايين التاجية (Coronary Artery Disease) · اللويحة العصيدية (Atherosclerotic Plaque) · إقفار عضلة القلب (Myocardial Ischemia).','Coronary Artery Disease (CAD) · Atherosclerosis · Acute Coronary Syndrome (ACS).','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-a_overview','dis-atrial-fibrillation','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','غياب موجات P المنتظمة في تخطيط القلب واستبدالها بتموجات رجفانية سريعة مع استجابة بطينية غير منتظمة إطلاقاً (Irregularly Irregular).','Uncoordinated atrial activation with absence of distinct P waves and an irregularly irregular ventricular response on ECG.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-b_epidemiology','dis-atrial-fibrillation','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','يرتبط بالتقدم في العمر، فرط ضغط الدم، أمراض الصمام التاجي، قصور القلب، وفرط نشاط الدرقية.','Associated with advancing age, hypertension, mitral valve disease, heart failure, and hyperthyroidism.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-c_pathophysiology','dis-atrial-fibrillation','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','بؤر منتبذة سريعة التفعيل (غالباً حول فوهات الأوردة الرئوية في الأذين الأيسر) مع دارات عودة دخول متعددة (Multiple Wavelet Re-entry) وتليف أذيني؛ يؤدي ركود الدم في لويحقة الأذين الأيسر (LAA) إلى تشكل خثرات قد تنتقل للدماغ.','Ectopic focal firing (typically from pulmonary vein sleeves) and re-entrant wavelets across remodeled atrial tissue; blood stasis in the left atrial appendage promotes thrombus formation.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-d_symptoms_red_flags','dis-atrial-fibrillation','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','خفقان غير منتظم، تعب، ضيق نفس، أو دوار. العلامات التحذيرية الطارئة (Red Flags): عجز عصبي بؤري مفاجئ (اشتباه سكتة دماغية صمية)، هبوط ضغط حاد، أو وذمة رئوية.','Palpitations, fatigue, dyspnea, or dizziness. Red Flags: sudden focal neurological deficit (embolic stroke), hemodynamic instability, or angina.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-e_diagnosis_differential','dis-atrial-fibrillation','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','تخطيط القلب الكهربائي (ECG) أو مراقبة هولتر، تخطيط صدى القلب لتقييم حجم الأذين الأيسر والصمامات، وفحص الهرمون الموجه للدرقية (TSH).','12-lead ECG or ambulatory Holter monitoring, echocardiography for left atrial size and valvular pathology, and thyroid panel (TSH).','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-f_non_pharmacological','dis-atrial-fibrillation','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','ضبط ضغط الدم والوزن، علاج انقطاع النفس النومي، وتجنب المنبهات المفرطة.','Blood pressure and weight management, treatment of obstructive sleep apnea, and trigger avoidance.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-g_pharmacotherapy_classes','dis-atrial-fibrillation','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) أدوية ضبط سرعة البطين (حاصرات بيتا، حاصرات الكالسيوم غير ثنائية الهيدروبيريدين)، 2) مضادات التخثر الفموية المباشرة (DOACs) للوقاية من السكتة الصمية وفق تقييم الخطر، 3) مضادات اللانظميات لإعادة النظم الجيبي.','Educational drug classes: 1) AV nodal rate-control agents (Beta-blockers, Non-DHP CCBs), 2) Anticoagulants (DOACs) for stroke prevention based on thromboembolic risk, 3) Rhythm-control antiarrhythmics.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-h_complications_prognosis','dis-atrial-fibrillation','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','السكتة الدماغية الإقفارية الصمية (Cardioembolic Stroke) واعتلال عضلة القلب المحرض بتسرع القلب.','Cardioembolic ischemic stroke and tachycardia-induced cardiomyopathy.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-i_sources_and_provenance','dis-atrial-fibrillation','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (BC81.3) · NICE NG196 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (BC81.3) · NICE NG196 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-atrial-fibrillation-j_terminology_and_links','dis-atrial-fibrillation','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الرجفان الأذيني (Atrial Fibrillation) · لويحقة الأذين الأيسر (Left Atrial Appendage) · الصمة الخثرية (Thromboembolism).','Atrial Fibrillation · Left Atrial Appendage (LAA) · Rate vs. Rhythm Control.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-a_overview','dis-bronchial-asthma','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','التهاب مزمن في الشعب الهوائية يسبب نوبات متكررة من الأزيز وضيق النفس والسعال وانسداد الجريان الهوائي القابل للعكس.','Chronic airway inflammation causing episodic wheezing, dyspnea, chest tightness, and cough with reversible expiratory airflow limitation.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-b_epidemiology','dis-bronchial-asthma','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','يرتبط بالتأتب الوراثي (Atopy)، التهاب الأنف التحسسي، التعرض للمحسسات البيئية، والعدوى الفيروسية التنفسية.','Linked to genetic atopy, allergic rhinitis, environmental allergens, and viral respiratory triggers.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-c_pathophysiology','dis-bronchial-asthma','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','استجابة مناعية بوساطة الخلايا التائية المساعدة (Th2) والغلوبولين المناعي IgE والخلايا البدينة واليوزينيات (Eosinophils)، مما يطلق الهستامين واللوكوترينات المسببة لتشنج العضلات الملساء القصبية ووذمة المخاطية وفرط إفراز المخاط.','Th2 lymphocyte, IgE, mast cell, and eosinophilic airway inflammation releasing histamine and cysteinyl leukotrienes, inducing bronchospasm, mucosal edema, and mucus plugging.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-d_symptoms_red_flags','dis-bronchial-asthma','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','أزيز زفيري، سعال ليلي أو صباحي، وضيق نفس. العلامات التحذيرية الطارئة (Red Flags): عدم القدرة على إكمال جملة واحدة، غياب أصوات التنفس (الصدر الصامت Silent Chest)، ازرقاق، أو نقص أكسجة شديد.','Expiratory wheeze, nocturnal cough, dyspnea. Red Flags: inability to speak in full sentences, silent chest on auscultation, cyanosis, or hypercapnia.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-e_diagnosis_differential','dis-bronchial-asthma','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','قياس وظائف الرئة (Spirometry) يظهر نقص نسبة FEV1/FVC مع تحسن في FEV1 بمقدار ≥12% و200 مل بعد موسع القصبات.','Spirometry demonstrating reduced FEV1/FVC ratio with positive bronchodilator reversibility (≥12% and ≥200 mL increase in FEV1).','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-f_non_pharmacological','dis-bronchial-asthma','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','تجنب المحسسات المهيجة، إيقاف التدخين والتعرض للتدخين السلبي، وإتقان تقنية استخدام البخاخات الاستنشاقية.','Trigger avoidance, smoking cessation, and verified inhaler technique education.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-g_pharmacotherapy_classes','dis-bronchial-asthma','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) الكورتيكوستيرويدات الاستنشاقية (ICS) كحجر أساس مضاد للالتهاب، 2) شادات مستقبلات بيتا-2 الودية قصيرة أو طويلة الأمد (SABA/LABA) لإرخاء العضلات الملساء القصبية، 3) مضادات مستقبلات اللوكوترين (LTRAs).','Educational drug classes: 1) Inhaled Corticosteroids (ICS) for underlying inflammation, 2) Beta-2 Agonists (SABA/LABA) for bronchodilation, 3) Leukotriene Receptor Antagonists.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-h_complications_prognosis','dis-bronchial-asthma','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','النوبات الربوية الحادة الشديدة (Status Asthmaticus) وإعادة قولبة جدار القصبات المزمن عند إهمال العلاج المضاد للالتهاب.','Severe acute exacerbations (status asthmaticus) and fixed airway remodeling if chronic inflammation is untreated.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-i_sources_and_provenance','dis-bronchial-asthma','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (CA23) · NICE NG80 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (CA23) · NICE NG80 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-bronchial-asthma-j_terminology_and_links','dis-bronchial-asthma','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الربو القصبي (Bronchial Asthma) · فرط الاستجابة القصبية (Bronchial Hyperresponsiveness) · قياس التنفس (Spirometry).','Bronchial Asthma · Airway Hyperresponsiveness · Bronchodilator Reversibility.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-a_overview','dis-copd','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','انسداد هوائي غير قابل للعكس الكامل يجمع بين التهاب القصيبات السادة المزمن (Chronic Bronchitis) والنفاخ الرئوي (Emphysema).','Persistent airflow limitation combining small airway disease (obstructive bronchiolitis) and parenchymal destruction (emphysema).','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-b_epidemiology','dis-copd','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','التعرض المزمن لدخان التبغ، الوقود الحيوي، والملوثات المهنية، أو عوز ألفا-1 أنتي تريبسين الوراثي.','Tobacco smoke, biomass fuel exposure, occupational dusts, and genetic alpha-1 antitrypsin deficiency.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-c_pathophysiology','dis-copd','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','إجهاد تأكسدي وتفوق أنزيمات البروتياز (الإيلاستاز من العدلات والبلعميات) على مضادات البروتياز، مما يحطم الألياف المرنة للجدران السنخية ويقلل الارتداد المرن للرئة ويؤدي لاحتباس الهواء (Air Trapping).','Oxidative stress and protease-antiprotease imbalance mediated by neutrophils and macrophages destroy alveolar elastic recoil, causing dynamic hyperinflation and gas trapping.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-d_symptoms_red_flags','dis-copd','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','زلة تنفسية مترقية مع الجهد، سعال مزمن منتج للقشع. العلامات التحذيرية الطارئة (Red Flags): ازرقاق مركزي، تخليط ذهني أو ميل للنوم (احتباس ثاني أكسيد الكربون)، أو استخدام شديد لعضلات التنفس المساعدة.','Progressive dyspnea, chronic productive cough. Red Flags: central cyanosis, hypercapnic encephalopathy/somnolence, or acute respiratory acidosis.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-e_diagnosis_differential','dis-copd','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','قياس التنفس (Spirometry) بعد موسع القصبات يثبت نسبة FEV1/FVC أقل من 0.70، مع تصوير الصدر وغازات الدم الشرياني في الحالات المتقدمة.','Post-bronchodilator spirometry confirming FEV1/FVC < 0.70, alongside chest imaging and arterial blood gas analysis when indicated.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-f_non_pharmacological','dis-copd','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','الإقلاع الفوري عن التدخين (الإجراء الأهم لإبطاء تدهور وظيفة الرئة)، التطعيمات التنفسية الموصى بها، والتأهيل الرئوي.','Smoking cessation (most effective intervention to slow FEV1 decline), pulmonary rehabilitation, and vaccinations.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-g_pharmacotherapy_classes','dis-copd','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) مضادات المسكارين طويلة الأمد (LAMA)، 2) شادات بيتا-2 طويلة الأمد (LABA)، 3) الكورتيكوستيرويدات الاستنشاقية في الأنماط ذات التفاقمات المتكررة وارتفاع اليوزينيات.','Educational drug classes: 1) Long-Acting Muscarinic Antagonists (LAMA), 2) Long-Acting Beta-2 Agonists (LABA), 3) Inhaled Corticosteroids in eosinophilic exacerbators.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-h_complications_prognosis','dis-copd','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','ارتفاع التوتر الرئوي، القلب الرئوي المزمن (Cor Pulmonale)، والقصور التنفسي المزمن.','Pulmonary hypertension, cor pulmonale (right heart failure), and chronic hypercapnic respiratory failure.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-i_sources_and_provenance','dis-copd','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (CA22) · NICE NG115 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (CA22) · NICE NG115 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-copd-j_terminology_and_links','dis-copd','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الداء الرئوي الانسدادي المزمن (COPD) · النفاخ الرئوي (Emphysema) · القلب الرئوي (Cor Pulmonale).','Chronic Obstructive Pulmonary Disease · Emphysema · Protease-Antiprotease Imbalance.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-a_overview','dis-pneumonia','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','التهاب حاد في الأسناخ الرئوية ناتج عن ممرضات بكتيرية (أشيعها المكورات الرئوية Streptococcus pneumoniae) أو فيروسية.','Acute parenchymal lung infection most commonly caused by Streptococcus pneumoniae, atypical bacteria, or respiratory viruses.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-b_epidemiology','dis-pneumonia','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','التقدم في العمر، الأمراض الرئوية أو القلبية المزمنة، التدخين، وضعف المناعة.','Advanced age, chronic cardiopulmonary comorbidities, smoking, and immunosuppression.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-c_pathophysiology','dis-pneumonia','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','وصول الميكروبات إلى الأسناخ يتجاوز دفاعات البلعميات السنخية، فيطلق السيتوكينات (IL-1, IL-6, TNF-alpha) التي تجذب العدلات وتزيد نفوذية الشعيرات، فتمتلئ الأسناخ بالسوائل (Consolidation) محدثة تحويلة داخل رئوية (Intrapulmonary Shunt).','Pathogen proliferation overwhelms alveolar macrophages, triggering cytokine release, capillary leak, neutrophil recruitment, and alveolar consolidation causing ventilation-perfusion (V/Q) mismatch.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-d_symptoms_red_flags','dis-pneumonia','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','حمى، سعال منتج لقشع قيحي، ألم صدري جنبي، وزلة تنفسية. العلامات التحذيرية الطارئة (Red Flags): تخليط ذهني جديد، تسرع تنفس ≥30/دقيقة، هبوط ضغط الدم، أو نقص تشبع الأكسجين <90%.','Fever, productive cough, pleuritic chest pain, dyspnea. Red Flags: new confusion, respiratory rate ≥30/min, hypotension, or hypoxemia (SpO2 <90%).','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-e_diagnosis_differential','dis-pneumonia','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','صورة الصدر الشعاعية لإثبات الارتشاح الفصي أو القصبي، تعداد الدم الكامل، مشعرات الالتهاب (CRP)، وتقييم الشدة السريرية.','Chest radiograph demonstrating new lobar/interstitial infiltrate, complete blood count, inflammatory markers, and severity stratification.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-f_non_pharmacological','dis-pneumonia','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','الإماهة الكافية، الراحة، ودعم الأكسجة عند الحاجة تحت إشراف طبي.','Adequate hydration, rest, and supplemental oxygen support when clinically indicated.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-g_pharmacotherapy_classes','dis-pneumonia','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: الصادات الحيوية المستهدفة لممرضات الجهاز التنفسي (البيتا-لاكتام، الماكروليدات، وغيرها) وفق الإرشادات السريرية المحلية ونتائج الزرع. [تنبيه: اختيار الصاد الحيوي وجرعته ومدته يتطلب وصفة طبية].','Educational drug classes: Empirical and culture-directed antibacterial/antiviral classes (Beta-lactams, Macrolides) per antimicrobial stewardship guidelines.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-h_complications_prognosis','dis-pneumonia','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','انصباب الجنب القيحي (Empyema)، خراج الرئة، وإنتان الدم (Sepsis).','Parapneumonic effusion/empyema, lung abscess, bacteremia, and sepsis.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-i_sources_and_provenance','dis-pneumonia','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (CA40) · NICE NG138 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (CA40) · NICE NG138 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-pneumonia-j_terminology_and_links','dis-pneumonia','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','ذات الرئة (Pneumonia) · التكثف السنخي (Alveolar Consolidation) · عدم تطابق التهوية والتروية (V/Q Mismatch).','Community-Acquired Pneumonia · Alveolar Consolidation · Ventilation-Perfusion Mismatch.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-a_overview','dis-gerd','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','اضطراب هضمي شائع ينجم عن فشل الحاجز المضاد للارتجاع عند الوصل المعدي المريئي.','Chronic digestive disorder resulting from failure of the gastroesophageal antireflux barrier.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-b_epidemiology','dis-gerd','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','الفتق الحجابي، السمنة البطنية، التدخين، وتناول الوجبات الدسمة المتأخرة.','Hiatal hernia, central obesity, smoking, delayed gastric emptying, and late fatty meals.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-c_pathophysiology','dis-gerd','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','تكرار الارتخاءات العابرة للمصرة المريئية السفلية (TLESRs) يعرض الظهارة الحرشفية للمريء لحمض الهيدروكلوريك والبيبسين، مما يسبب التهاب المريء التآكلي أو الحؤول المعوي (مريء باريت).','Transient lower esophageal sphincter relaxations (TLESRs) expose squamous esophageal mucosa to hydrochloric acid and pepsin, inducing erosive esophagitis or Barrett metaplasia.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-d_symptoms_red_flags','dis-gerd','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','حرقة الفؤاد خلف القص (Heartburn) والقلس الحمضي. العلامات التحذيرية الطارئة (Red Flags): عسر بلع مترقٍ (Dysphagia)، ألم عند البلع، نقص وزن غير مفسر، أو قيء مدمى/تغوط أسود.','Retrosternal heartburn and acid regurgitation. Red Flags: progressive dysphagia, odynophagia, unexplained weight loss, or gastrointestinal bleeding.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-e_diagnosis_differential','dis-gerd','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','التقييم السريري، والتنظير الهضمي العلوي (EGD) عند وجود علامات تحذيرية أو عدم الاستجابة، وقياس باهاء المريء (pH monitoring).','Clinical evaluation, upper gastrointestinal endoscopy (EGD) when alarm features are present, and ambulatory esophageal pH-impedance monitoring.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-f_non_pharmacological','dis-gerd','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','رفع رأس السرير، تجنب الأكل قبل النوم بـ 3 ساعات، خفض الوزن، وتقليل الأطعمة المرخية للمصرة (الدهون، الكافيين، الشوكولاتة).','Head-of-bed elevation, avoiding meals within 3 hours of bedtime, weight reduction, and limiting LES-relaxing triggers.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-g_pharmacotherapy_classes','dis-gerd','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) مثبطات مضخة البروتون (PPIs) التي تثبط H+/K+ ATPase في الخلايا الجدارية، 2) حاصرات مستقبلات الهستامين H2، 3) مضادات الحموضة والألجينات الموضعية.','Educational drug classes: 1) Proton Pump Inhibitors (irreversible H+/K+ ATPase inhibition), 2) H2 Receptor Antagonists, 3) Antacids and Alginate rafts.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-h_complications_prognosis','dis-gerd','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','تضيق المريء الهضمي، التهاب المريء التقرحي، ومريء باريت (Barrett Esophagus).','Esophageal stricture, erosive esophagitis, and Barrett intestinal metaplasia.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-i_sources_and_provenance','dis-gerd','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (DA22) · NICE CG184 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (DA22) · NICE CG184 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-gerd-j_terminology_and_links','dis-gerd','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الارتجاع المعدي المريئي (GERD) · المصرة المريئية السفلية (Lower Esophageal Sphincter) · الخلايا الجدارية (Parietal Cells).','Gastroesophageal Reflux Disease · Lower Esophageal Sphincter (LES) · Proton Pump.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-a_overview','dis-peptic-ulcer','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','تقرح مخاطي هضمي يحدث غالباً في بصلة الاثني عشر أو الغار المعدي.','Mucosal ulceration occurring predominantly in the duodenal bulb or gastric antrum.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-b_epidemiology','dis-peptic-ulcer','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','العدوى ببكتيريا الملوية البوابية (Helicobacter pylori) والاستخدام المزمن لمضادات الالتهاب غير الستيرويدية (NSAIDs).','Helicobacter pylori infection and chronic use of nonsteroidal anti-inflammatory drugs (NSAIDs).','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-c_pathophysiology','dis-peptic-ulcer','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','تفرز الملوية البوابية إنزيم اليورياز والسموم الخلوية مضعفة الحاجز المخاطي، بينما تثبط مضادات الالتهاب غير الستيرويدية إنزيم COX-1 مما يقلل تصنيع البروستاغلاندينات الواقية (PGE2/PGI2) المسؤولة عن إفراز المخاط والبيكربونات والتروية الدموية المخاطية.','H. pylori urease and cytotoxins disrupt mucosal integrity, while NSAIDs inhibit COX-1-mediated prostaglandin synthesis, reducing mucus, bicarbonate, and mucosal blood flow.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-d_symptoms_red_flags','dis-peptic-ulcer','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','ألم شرسوفي حارق. العلامات التحذيرية الطارئة (Red Flags): قيء دموي (Hematemesis)، براز أسود قارّي (Melena)، أو ألم بطني مفاجئ شديد مع صلابة بطنية (انثقاب القرحة).','Epigastric burning pain. Red Flags: hematemesis, melena, unexplained anemia, or sudden severe peritonitic pain (perforation).','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-e_diagnosis_differential','dis-peptic-ulcer','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','فحص مستضد الملوية البوابية في البراز أو اختبار النفس باليوريا، والتنظير الهضمي العلوي مع الخزعة.','Urea breath test or stool antigen testing for H. pylori, and upper endoscopy (EGD) with biopsy.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-f_non_pharmacological','dis-peptic-ulcer','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','إيقاف مضادات الالتهاب غير الستيرويدية المسببة والتوقف عن التدخين.','Discontinuation of offending NSAIDs and smoking cessation.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-g_pharmacotherapy_classes','dis-peptic-ulcer','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) مثبطات مضخة البروتون لتثبيط الإفراز الحمضي وتمكين التئام المخاطية، 2) البروتوكولات المعتمدة لاستئصال الملوية البوابية بإشراف طبي، 3) واقيات المخاطية (مثل السوكرالفات).','Educational drug classes: 1) Proton Pump Inhibitors for acid suppression and mucosal healing, 2) Guideline-directed H. pylori eradication protocols, 3) Mucosal cytoprotectants.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-h_complications_prognosis','dis-peptic-ulcer','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','النزف الهضمي العلوي، انثقاب القرحة، وانسداد مخرج المعدة.','Upper gastrointestinal hemorrhage, viscus perforation, and gastric outlet obstruction.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-i_sources_and_provenance','dis-peptic-ulcer','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (DA60) · NICE CG184 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (DA60) · NICE CG184 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-peptic-ulcer-j_terminology_and_links','dis-peptic-ulcer','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','القرحة الهضمية (Peptic Ulcer) · الملوية البوابية (Helicobacter pylori) · البروستاغلاندينات الواقية (Cytoprotective Prostaglandins).','Peptic Ulcer Disease (PUD) · Helicobacter pylori · COX-1 Mucosal Protection.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-a_overview','dis-nafld-masld','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','طيف يمتد من التنكس الدهني الكبدي البسيط إلى التهاب الكبد الدهني الاستقلابي (MASH/NASH) القابل للترقي إلى التليف والتشمع.','Spectrum ranging from simple hepatic steatosis to steatohepatitis (MASH/NASH) with progressive fibrosis.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-b_epidemiology','dis-nafld-masld','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','السمنة المركزية، السكري من النمط الثاني، اضطراب شحوم الدم، وفرط ضغط الدم.','Central adiposity, type 2 diabetes mellitus, dyslipidemia, and metabolic syndrome.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-c_pathophysiology','dis-nafld-masld','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','تؤدي مقاومة الأنسولين المحيطية إلى زيادة تحلل الدهون وتدفق الأحماض الدهنية الحرة إلى الكبد مع زيادة تصنيع الدهون الكبدي (De novo lipogenesis)، مما يولد سمية دهنية وإجهاداً تأكسدياً ينشط خلايا إيتو النجمية (Hepatic Stellate Cells) المفرزة للكولاجين.','Insulin resistance increases free fatty acid flux and hepatic de novo lipogenesis, causing lipotoxicity, oxidative stress, and activation of collagen-depositing hepatic stellate cells.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-d_symptoms_red_flags','dis-nafld-masld','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','غالباً لا عرضي. العلامات التحذيرية (Red Flags) لتقدم التليف والتشمع: يرقان، حبن بطني (Ascites)، اعتلال دماغي كبدي، أو نزف دوالي المريء.','Typically asymptomatic early. Red Flags of decompensated cirrhosis: jaundice, ascites, hepatic encephalopathy, or variceal hemorrhage.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-e_diagnosis_differential','dis-nafld-masld','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','خمائر الكبد (ALT, AST)، حساب مؤشرات التليف غير الباضعة (FIB-4)، قياس مرونة الكبد (FibroScan)، والتصوير بالأمواج فوق الصوتية.','Liver transaminases, non-invasive fibrosis scoring (FIB-4), transient elastography (FibroScan), and hepatic ultrasonography.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-f_non_pharmacological','dis-nafld-masld','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','إنقاص الوزن التدريجي (7-10% يحسن الالتهاب الكبدي والتليف)، الحمية المتوسطية، والتمارين الهوائية والمقاومة.','Sustained weight reduction (7-10% body weight improves steatohepatitis), Mediterranean diet, and regular physical activity.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-g_pharmacotherapy_classes','dis-nafld-masld','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: أدوية ضبط الاستقلاب ومقاومة الأنسولين (شادات GLP-1، محسسات الأنسولين) وخافضات الشحوم للوقاية القلبية الوعائية المصاحبة.','Educational drug classes: Metabolic and insulin-sensitizing agents (GLP-1 receptor agonists, SGLT2i) and statins for concurrent cardiovascular risk.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-h_complications_prognosis','dis-nafld-masld','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','التشمع الكبدي، فرط ضغط الوريد البابي، وسرطانة الخلية الكبدية (HCC).','Cirrhosis, portal hypertension, and hepatocellular carcinoma.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-i_sources_and_provenance','dis-nafld-masld','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (DB92) · NICE NG49 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (DB92) · NICE NG49 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nafld-masld-j_terminology_and_links','dis-nafld-masld','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','التنكس الدهني الكبدي (Hepatic Steatosis) · الخلايا النجمية الكبدية (Hepatic Stellate Cells) · مقاومة الأنسولين (Insulin Resistance).','MASLD / NAFLD · Steatohepatitis · Hepatic Stellate Cell Fibrogenesis.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-a_overview','dis-ckd','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','فقدان تدريجي وغير عكوس لعدد النفرونات الوظيفية، ويؤثر مباشرة في الحرائك الدوائية وتعديل جرعات الأدوية المطروحة كلوياً.','Progressive, irreversible nephron loss requiring staging by GFR (G1-G5) and albuminuria (A1-A3) and renal dose adjustment for hydrophilic drugs.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-b_epidemiology','dis-ckd','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','السكري من النمط الثاني والنمط الأول، فرط ضغط الدم الشرياني، التهابات كبيبات الكلى، وداء الكلية متعددة الكيسات.','Diabetes mellitus, systemic hypertension, glomerulonephritis, and polycystic kidney disease.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-c_pathophysiology','dis-ckd','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','يؤدي فقدان جزء من النفرونات إلى فرط ترشيح تعويضي (Adaptive Hyperfiltration) وارتفاع الضغط داخل الكبيبات المتبقية بوساطة أنجيوتنسين II، مما يسبب تصلب الكبيبات البؤري والتليف الأنبوبي الخلالي ونقص تصنيع الإريثروبويتين والكالسيتريول.','Nephron loss induces compensatory intraglomerular hypertension and hyperfiltration in remaining nephrons via Angiotensin II, accelerating glomerulosclerosis, tubulointerstitial fibrosis, anemia, and mineral-bone disorder.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-d_symptoms_red_flags','dis-ckd','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','تعب، وذمة، حكة، غثيان في المراحل المتقدمة. العلامات التحذيرية الطارئة (Red Flags): فرط بوتاسيوم الدم الشديد، وذمة رئوية مقاومة، التهاب التامور اليوريميائي، أو اعتلال دماغي يوريميائي.','Fatigue, edema, pruritus in advanced stages. Red Flags: life-threatening hyperkalemia, refractory pulmonary edema, uremic pericarditis, or encephalopathy.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-e_diagnosis_differential','dis-ckd','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','تقدير معدل الترشيح الكبيبي (eGFR) من كرياتينين المصل أو السيستاتين C، نسبة الألبومين إلى الكرياتينين في البول (uACR)، وتصوير الكليتين بالأمواج فوق الصوتية.','Serum creatinine/cystatin C eGFR calculation, urine albumin-to-creatinine ratio (uACR), electrolytes, and renal ultrasonography.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-f_non_pharmacological','dis-ckd','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','ضبط ضغط الدم وسكر الدم، تقليل الصوديوم الغذائي، وتجنب الأدوية السامة للكلية (مثل NSAIDs ومواد التباين الوريدية غير الضرورية).','Strict blood pressure and glycemic control, sodium restriction, and avoidance of nephrotoxins (e.g., NSAIDs).','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-g_pharmacotherapy_classes','dis-ckd','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية لإبطاء تدهور الكلية: 1) مثبطات ACE أو ARBs لخفض الضغط داخل الكبيبة وتقليل البيلة الألبومينية، 2) مثبطات SGLT2 التي تعيد التلقيم الراجع الأنبوبي الكبيبي، 3) تعويض الحديد والإريثروبويتين لفقر الدم الكلوي.','Educational drug classes: 1) ACEIs/ARBs (efferent arteriolar dilation reducing intraglomerular pressure), 2) SGLT2 Inhibitors (restoring tubuloglomerular feedback), 3) CKD-MBD and anemia therapies.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-h_complications_prognosis','dis-ckd','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','فقر الدم الكلوي، اضطراب العظم والمعادن (CKD-MBD)، الحماض الاستقلابي، والقصور الكلوي النهائي (ESRD).','Renal anemia, CKD mineral and bone disorder (secondary hyperparathyroidism), metabolic acidosis, and end-stage kidney disease.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-i_sources_and_provenance','dis-ckd','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (GB61) · NICE NG203 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (GB61) · NICE NG203 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ckd-j_terminology_and_links','dis-ckd','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','المرض الكلوي المزمن (CKD) · معدل الترشيح الكبيبي (Glomerular Filtration Rate) · البيلة الألبومينية (Albuminuria).','Chronic Kidney Disease · Glomerular Filtration Rate (eGFR) · Intraglomerular Hypertension.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-a_overview','dis-aki','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','تُصنف تشريحياً وفيزيولوجياً إلى أسباب قبل كلوية (Pre-renal)، وكلوية داخلية (Intrinsic)، وبعد كلوية انسدادية (Post-renal).','Classified pathophysiologically into pre-renal hypoperfusion, intrinsic renal parenchymal injury, and post-renal urinary tract obstruction.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-b_epidemiology','dis-aki','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','التجفاف، الإنتان (Sepsis)، هبوط الضغط، الأدوية السامة للكلية (NSAIDs، الأمينوغليكوزيدات)، أو انسداد السبيل البولي.','Volume depletion, sepsis, hypotension, nephrotoxic medications (NSAIDs, aminoglycosides, radiocontrast), or outflow obstruction.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-c_pathophysiology','dis-aki','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','في النمط قبل الكلوي ينخفض تدفق الدم الكلوي؛ وتؤدي المشاركة الخاطئة بين مثبطات ACE/ARBs والمدرات ومضادات الالتهاب غير الستيرويدية (Triple Whammy) إلى انهيار الضغط الترشيحي الكبيبي أو النخر الأنبوبي الحاد (ATN).','Renal hypoperfusion or nephrotoxic/ischemic insult causes acute tubular necrosis (ATN); combining ACEIs/ARBs, diuretics, and NSAIDs (Triple Whammy) abolishes glomerular autoregulation.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-d_symptoms_red_flags','dis-aki','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','شح البول (Oliguria < 0.5 mL/kg/h)، وذمة، تعب. العلامات التحذيرية الطارئة (Red Flags): انقطاع البول التام (Anuria)، فرط بوتاسيوم الدم مع تغيرات تخطيط القلب، أو حماض استقلابي شديد.','Oliguria, fluid overload. Red Flags: complete anuria, hyperkalemic ECG changes (peaked T waves), or refractory metabolic acidosis.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-e_diagnosis_differential','dis-aki','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','مراقبة كرياتينين المصل المتسلسل وحجم الصبيب البولي، فحص راسب البول المجهري، وإيكو الكليتين والمثانة لنفي الانسداد.','Serial serum creatinine, hourly urine output monitoring, urine microscopy (muddy brown casts in ATN), and renal ultrasound to exclude hydronephrosis.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-f_non_pharmacological','dis-aki','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','إيقاف الأدوية السامة للكلية فوراً، تصحيح حالة الحجم الدوراني، وتعديل جرعات الأدوية المطروحة كلوياً.','Immediate cessation of nephrotoxic agents, hemodynamic volume optimization, and renal dose adjustment.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-g_pharmacotherapy_classes','dis-aki','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','المبادئ الدوائية التعليمية: تجنب الأدوية المؤذية للكلية، استعادة التروية في الأسباب قبل الكلوية، وإدارة اضطرابات الشوارد في المستشفى.','Educational pharmacotherapy principles: Nephrotoxin stewardship, hemodynamic restoration, and inpatient electrolyte management.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-h_complications_prognosis','dis-aki','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','فرط بوتاسيوم الدم المهدد للحياة، الوذمة الرئوية، والتحول إلى مرض كلوي مزمن.','Hyperkalemia, pulmonary edema, uremia, and progression to chronic kidney disease.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-i_sources_and_provenance','dis-aki','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (GB60) · NICE NG148 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (GB60) · NICE NG148 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-aki-j_terminology_and_links','dis-aki','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الأذية الكلوية الحادة (AKI) · النخر الأنبوبي الحاد (Acute Tubular Necrosis) · شح البول (Oliguria).','Acute Kidney Injury · Pre-renal / Intrinsic / Post-renal · Acute Tubular Necrosis.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-a_overview','dis-nephrolithiasis','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','ترسب بلوري في السبيل البولي العلوي، وتمثل حصيات الكالسيوم نحو 80% من الحالات.','Crystalline concretion in the collecting system; calcium oxalate/phosphate stones account for ~80% of cases.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-b_epidemiology','dis-nephrolithiasis','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','قلة شرب السوائل، فرط كالسيوم البول، فرط أوكسالات البول، أو فرط حمض يوريك البول وانخفاض باهاء البول.','Low fluid intake, hypercalciuria, hyperoxaluria, hyperuricosuria, and acidic urinary pH.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-c_pathophysiology','dis-nephrolithiasis','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','فرط إشباع البول (Supersaturation) بالأملاح المكونة للحصيات مع نقص المثبطات الطبيعية للتبلور (مثل السيترات البولية)، وعند انحشار الحصاة في الحالب يرتفع الضغط داخل الحويضة وتتقلص العضلات الملساء الحالبية بشدة.','Urinary supersaturation coupled with reduced crystallization inhibitors (e.g., urinary citrate) promotes nucleation; ureteral impaction triggers prostaglandin-mediated spasm and hydronephrosis.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-d_symptoms_red_flags','dis-nephrolithiasis','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','ألم خاصرة حاد ماص (القولنج الكلوي) ينتشر إلى المغبن مع بيلة دموية. العلامات التحذيرية الطارئة (Red Flags): حمى وعرواءات مرافقة لانسداد الحالب (التهاب حويضة وكلية انسدادي — حالة إسعافية جراحية)، أو انقطاع البول.','Severe colicky flank pain radiating to the groin with hematuria. Red Flags: fever/rigors with an obstructing stone (infected hydronephrosis/urosepsis) or anuria.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-e_diagnosis_differential','dis-nephrolithiasis','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','فحص البول العام، التصوير بالأمواج فوق الصوتية، أو التصوير المقطعي الحلزوني غير الظليل (Non-contrast CT KUB).','Urinalysis, renal ultrasonography, or low-dose non-contrast helical CT of the kidneys, ureters, and bladder.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-f_non_pharmacological','dis-nephrolithiasis','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','زيادة مدخول السوائل لتحقيق حجم بول يومي >2 إلى 2.5 لتر، وتقليل الصوديوم والبروتين الحيواني المفرط.','High oral fluid intake targeting >2-2.5 L/day urine output, dietary sodium moderation, and normal dietary calcium.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-g_pharmacotherapy_classes','dis-nephrolithiasis','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) المسكنات لتخفيف تشنج الحالب والألم الحاد، 2) حاصرات مستقبلات ألفا-1 الانتقائية لإرخاء العضلات الملساء في أسفل الحالب، 3) سترات البوتاسيوم أو الثيازيدات للوقاية من النكس وفق تركيب الحصاة.','Educational drug classes: 1) Analgesics for acute renal colic, 2) Alpha-1 blockers for distal ureteral smooth muscle relaxation, 3) Potassium citrate or thiazides for metabolic recurrence prevention.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-h_complications_prognosis','dis-nephrolithiasis','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','استسقاء الكلية الانسدادي (Hydronephrosis) والإنتان البولي في حال ترافق الانسداد بالخمج.','Obstructive hydronephrosis, acute kidney injury, and urosepsis.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-i_sources_and_provenance','dis-nephrolithiasis','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (GB70) · NICE NG118 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (GB70) · NICE NG118 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-nephrolithiasis-j_terminology_and_links','dis-nephrolithiasis','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الحصيات الكلوية (Nephrolithiasis) · القولنج الكلوي (Renal Colic) · استسقاء الكلية (Hydronephrosis).','Nephrolithiasis · Ureteral Colic · Urinary Supersaturation.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-a_overview','dis-ischemic-stroke','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','تشكل السكتات الإقفارية نحو 85% من مجمل السكتات الدماغية، وتعتمد نتيجتها على سرعة استعادة التروية لإنقاذ منطقة الظل الإقفاري (Ischemic Penumbra).','Accounts for ~85% of all strokes; clinical recovery depends on rapid reperfusion to salvage the ischemic penumbra surrounding the infarct core.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-b_epidemiology','dis-ischemic-stroke','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','فرط ضغط الدم الشرياني، الرجفان الأذيني، تصلب الشرايين السباتية، السكري، والتدخين.','Hypertension, atrial fibrillation, carotid atherosclerosis, diabetes mellitus, and smoking.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-c_pathophysiology','dis-ischemic-stroke','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','يؤدي انقطاع التروية الشريانية إلى نفاد الـ ATP الخلوي وفشل مضخة Na+/K+ ATPase والسمية الاستثارية بوساطة الغلوتامات (Glutamate Excitotoxicity) وتدفق الكالسيوم داخل العصبونات.','Arterial occlusion depletes neuronal ATP, causing Na+/K+ pump failure, glutamate-mediated excitotoxicity, intracellular calcium overload, and neuronal necrosis.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-d_symptoms_red_flags','dis-ischemic-stroke','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','علامات FAST الطارئة (Red Flags): تدلي شق الوجه، ضعف أو خدر مفاجئ في الذراع أو الساق في شق واحد، ثقل اللسان أو الحبسة الكلامية (Aphasia)، أو فقدان الرؤية المفاجئ — تستدعي الإسعاف الفوري.','Emergency FAST Red Flags: Facial droop, unilateral Arm/leg motor weakness, Speech dysarthria/aphasia, Time-critical emergency hospital transport.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-e_diagnosis_differential','dis-ischemic-stroke','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','التصوير المقطعي المحوسب للدماغ بدون حقن (Non-contrast Head CT) فوراً لاستبعاد النزف الدماغي، وتصوير الأوعية المقطعي أو الرنين المغناطيسي للانتشار (DWI-MRI).','Immediate non-contrast head CT to exclude hemorrhage, CT angiography, and diffusion-weighted MRI (DWI).','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-f_non_pharmacological','dis-ischemic-stroke','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','التأهيل العصبي والحركي والكلامي المبكر، وضبط عوامل الخطورة الوعائية بدقة.','Multidisciplinary neurorehabilitation (physical, occupational, speech therapy) and strict secondary vascular risk modification.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-g_pharmacotherapy_classes','dis-ischemic-stroke','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) حالات الخثرة الوريدية داخل المستشفى في النافذة الزمنية المحددة بعد نفي النزف، 2) مضادات تكدس الصفائح للوقاية الثانوية غير الصمية، 3) مضادات التخثر الفموية في السكتة ذات المنشأ القلبي الصمي، 4) الستاتينات عالية الشدة.','Educational drug classes: 1) Inpatient intravenous thrombolytics within strict time windows after ruling out bleed, 2) Antiplatelets for non-cardioembolic secondary prevention, 3) Anticoagulants for cardioembolic stroke, 4) High-intensity statins.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-h_complications_prognosis','dis-ischemic-stroke','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','الوذمة الدماغية، التحول النزفي، والإعاقة الحركية أو الكلامية المزمنة.','Cerebral edema, hemorrhagic transformation, post-stroke dysphagia, and long-term motor/cognitive disability.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-i_sources_and_provenance','dis-ischemic-stroke','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (8B11) · NICE NG128 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (8B11) · NICE NG128 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-ischemic-stroke-j_terminology_and_links','dis-ischemic-stroke','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','السكتة الإقفارية (Ischemic Stroke) · منطقة الظل الإقفاري (Ischemic Penumbra) · السمية الاستثارية (Excitotoxicity).','Acute Ischemic Stroke · Ischemic Penumbra · Cardioembolism · Circle of Willis.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-a_overview','dis-type2-diabetes','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','يمثل أكثر من 90% من حالات السكري، ويؤثر في الأوعية الدموية الكبيرة (القلب والدماغ) والدقيقة (الشبكية والكلية والأعصاب).','Accounts for >90% of diabetes cases and drives both macrovascular (coronary, cerebrovascular) and microvascular (nephropathy, retinopathy, neuropathy) disease.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-b_epidemiology','dis-type2-diabetes','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','السمنة الحشوية، قلة النشاط البدني، الاستعداد الوراثي، والسكري الحملي السابق.','Visceral adiposity, sedentary lifestyle, polygenic inheritance, and prior gestational diabetes.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-c_pathophysiology','dis-type2-diabetes','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','خلل الإشارة بعد مستقبل الأنسولين يقلل انتقال نواقل GLUT4 في العضلات الهيكلية والنسيج الدهني، مع زيادة استحداث السكر الكبدي (Gluconeogenesis) وضعف تأثير هرمونات الإنكريتين (GLP-1) وتناقص كتلة خلايا بيتا.','Impaired post-receptor insulin signaling reduces GLUT4 translocation in skeletal muscle while unrestrained hepatic gluconeogenesis, blunted incretin effect, and beta-cell lipotoxicity sustain hyperglycemia.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-d_symptoms_red_flags','dis-type2-diabetes','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','عطش مفرط (Polydipsia)، بوال (Polyuria)، تعب، أو تشوش رؤية. العلامات التحذيرية الطارئة (Red Flags): تجفاف شديد وتخليط ذهني (حالة فرط الأسمولية فرط سكر الدم HHS)، أو تنفس كوسماول مع حماض كيتوني سكري (DKA)، أو هبوط سكر الدم الشديد.','Polyuria, polydipsia, fatigue, blurred vision. Red Flags: severe dehydration/obtundation (Hyperosmolar Hyperglycemic State), Kussmaul breathing (Diabetic Ketoacidosis), or severe hypoglycemia.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-e_diagnosis_differential','dis-type2-diabetes','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','الخضاب الغليكوزيلي (HbA1c ≥ 6.5%)، سكر الدم الصيامي (FPG ≥ 126 mg/dL)، أو اختبار تحمل الجلوكوز الفموي، مع الفحص الدوري للبول (uACR) وفحص قعر العين والقدمين.','HbA1c ≥6.5%, fasting plasma glucose ≥126 mg/dL, or 2-hour OGTT ≥200 mg/dL, plus annual urine ACR, retinal, and foot neurovascular screening.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-f_non_pharmacological','dis-type2-diabetes','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','التغذية الطبية المتوازنة منخفضة السكريات البسيطة، خفض الوزن، والتمارين الهوائية وتمارين المقاومة المنتظمة.','Medical nutrition therapy, weight management, and combined aerobic/resistance exercise.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-g_pharmacotherapy_classes','dis-type2-diabetes','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) البيغوانيدات (الميتفورمين) لخفض استحداث السكر الكبدي وتحسين حساسية الأنسولين، 2) مثبطات SGLT2 وشادات مستقبلات GLP-1 ذات الحماية القلبية والكلوية المثبتة، 3) مثبطات DPP-4 والأنسولين عند الحاجة.','Educational drug classes: 1) Biguanides (Metformin — suppresses hepatic gluconeogenesis), 2) SGLT2 Inhibitors & GLP-1 Receptor Agonists (cardiorenal protection), 3) DPP-4 Inhibitors & Insulins.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-h_complications_prognosis','dis-type2-diabetes','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','اعتلال الكلية السكري، اعتلال الشبكية السكري، اعتلال الأعصاب المحيطية والقدم السكرية، وأمراض القلب الإقفارية.','Diabetic nephropathy, retinopathy, peripheral neuropathy, diabetic foot ulceration, and atherosclerotic cardiovascular disease.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-i_sources_and_provenance','dis-type2-diabetes','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (5A11) · NICE NG28 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (5A11) · NICE NG28 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-type2-diabetes-j_terminology_and_links','dis-type2-diabetes','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','السكري من النمط الثاني (Type 2 Diabetes) · مقاومة الأنسولين (Insulin Resistance) · الخضاب الغليكوزيلي (HbA1c).','Type 2 Diabetes Mellitus · GLUT4 Translocation · Incretin Pathway (GLP-1).','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-a_overview','dis-hypothyroidism','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','قصور وظيفي في الغدة الدرقية يتظاهر بارتفاع الهرمون الموجه للدرقية (TSH) وانخفاض الثيروكسين الحر (Free T4).','Endocrine hypofunction characterized by elevated pituitary TSH and reduced circulating free thyroxine (fT4).','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-b_epidemiology','dis-hypothyroidism','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','التهاب الدرقية المناعي الذاتي (داء هاشيموتو Hashimoto Thyroiditis)، نقص اليود، أو بعد استئصال الدرقية أو اليود المشع.','Autoimmune Hashimoto thyroiditis (anti-TPO antibodies), iodine deficiency, or post-thyroidectomy/radioiodine therapy.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-c_pathophysiology','dis-hypothyroidism','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','نقص تنشيط مستقبلات هرمون الدرقية النووية يقلل نسخ الجينات المسؤولة عن Na+/K+ ATPase وأكاسيد الميتوكوندريا ومستقبلات بيتا-1 القلبية، مما يسبب بطء القلب وتراكم الغليكوزأمينوغليكان في الأدمة (الوذمة المخاطية).','Reduced nuclear thyroid hormone receptor transcription decreases Na+/K+ ATPase activity, basal metabolic rate, and cardiac beta-1 receptor density, while dermal glycosaminoglycan accumulation causes myxedema.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-d_symptoms_red_flags','dis-hypothyroidism','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','تعب، عدم تحمل البرد، زيادة وزن، إمساك، بطء قلب، وجفاف الجلد. العلامات التحذيرية الطارئة (Red Flags): انخفاض حرارة الجسم وتغير الوعي وبطء التنفس (غيبوبة الوذمة المخاطية Myxedema Coma).','Fatigue, cold intolerance, weight gain, constipation, bradycardia, dry skin. Red Flags: hypothermia, obtundation, and hypoventilation (myxedema coma).','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-e_diagnosis_differential','dis-hypothyroidism','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','معايرة الهرمون الموجه للدرقية (TSH — الفحص الأولي الأدق) والثيروكسين الحر (Free T4) وأضداد البيروكسيداز الدرقي (Anti-TPO).','Serum TSH (primary screening test), free T4 (fT4), and anti-thyroid peroxidase (anti-TPO) antibodies.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-f_non_pharmacological','dis-hypothyroidism','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','ضمان كفاية اليود الغذائي، وتناول هرمون التعويض صباحاً على معدة فارغة بعيداً عن أملاح الحديد والكالسيوم التي تعيق امتصاصه.','Consistent fasting administration of hormone replacement separated from iron, calcium, and bile acid sequestrants.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-g_pharmacotherapy_classes','dis-hypothyroidism','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئة الدوائية التعليمية: طليعة الهرمون الصنعي ليفوثيروكسين (Levothyroxine T4) الذي يتحول محيطياً بواسطة إنزيمات نزع اليود (Deiodinases) إلى الشكل النشط T3.','Educational drug class: Synthetic levothyroxine (L-T4), converted peripherally via deiodinases to biologically active T3.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-h_complications_prognosis','dis-hypothyroidism','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','فرط شحميات الدم الثانوي، انصباب التامور، وغيبوبة الوذمة المخاطية عند الإهمال الشديد.','Secondary hypercholesterolemia, pericardial effusion, and myxedema coma if untreated.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-i_sources_and_provenance','dis-hypothyroidism','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (5A00) · NICE NG145 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (5A00) · NICE NG145 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-hypothyroidism-j_terminology_and_links','dis-hypothyroidism','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','قصور الدرقية (Hypothyroidism) · الهرمون الموجه للدرقية (TSH) · الوذمة المخاطية (Myxedema).','Primary Hypothyroidism · Hashimoto Thyroiditis · Levothyroxine Deiodination.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-a_overview','dis-iron-deficiency-anemia','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','فقر دم صغير الكريات (MCV < 80 fL) ناقص الصباغ ينجم عن عدم كفاية الحديد المتاح لتصنيع الهيموغلوبين.','Microcytic, hypochromic anemia resulting from insufficient iron availability for erythroblast hemoglobin synthesis.','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-b_epidemiology','dis-iron-deficiency-anemia','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','نقص المدخول الغذائي، سوء الامتصاص في الاثني عشر (مثل الداء البطني)، زيادة الاحتياج (الحمل والنمو)، أو الفقد الدموي المزمن الخفي (الهضمي أو النسائي).','Inadequate dietary intake, duodenal malabsorption (celiac disease), increased demand (pregnancy), or chronic occult gastrointestinal/menstrual blood loss.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-c_pathophysiology','dis-iron-deficiency-anemia','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','استنفاد الفيريتين المخزون في الجهاز الشبكي البطاني يؤدي لارتفاع الترانسفيرين الكلي (TIBC) وانخفاض حديد المصل، فتخضع طلائع الكريات الحمر لانقسامات إضافية مع كمية هيموغلوبين أقل.','Depletion of reticuloendothelial ferritin stores lowers serum iron and elevates total iron-binding capacity (TIBC), impairing protoporphyrin IX heme incorporation in bone marrow normoblasts.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-d_symptoms_red_flags','dis-iron-deficiency-anemia','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','شحوب الأغشية المخاطية، وهن عام، زلة جهدية، تقصف الأظافر. العلامات التحذيرية (Red Flags): فقر دم بعوز الحديد لدى البالغين يستوجب تقصي مصدر نزف هضمي خفي، أو تسرع قلب شديد وألم صدري.','Pallor, fatigue, exertional dyspnea, koilonychia. Red Flags: unexplained IDA in adults requiring investigation for occult GI malignancy/bleeding, or hemodynamic compromise.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-e_diagnosis_differential','dis-iron-deficiency-anemia','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','تعداد الدم الكامل (انخفاض Hb و MCV و MCH)، انخفاض فيريتين المصل (الفحص الأدق لمخازن الحديد)، انخفاض إشباع الترانسفيرين، وارتفاع TIBC.','CBC showing low hemoglobin and MCV, low serum ferritin (most specific marker of depleted stores), low transferrin saturation, and elevated TIBC.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-f_non_pharmacological','dis-iron-deficiency-anemia','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','تناول الأغذية الغنية بالحديد الهيمي وغير الهيمي مع فيتامين C الذي يعزز اختزال الحديد وامتصاصه في الاثني عشر، وتجنب الشاي والكالسيوم بالتزامن المباشر مع الحديد.','Dietary heme/non-heme iron intake paired with ascorbic acid (vitamin C) to enhance duodenal Fe2+ absorption, while separating tea/calcium intake.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-g_pharmacotherapy_classes','dis-iron-deficiency-anemia','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: أملاح الحديد الفموية أو مستحضرات الحديد الوريدية (في حالات سوء الامتصاص أو عدم التحمل الشديد) مع استمرار التعويض حتى ملء مخازن الفيريتين وعلاج السبب الأصلي.','Educational drug classes: Oral ferrous salts or parenteral iron formulations alongside definitive treatment of the underlying cause of iron loss.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-h_complications_prognosis','dis-iron-deficiency-anemia','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','ضعف الأداء البدني والمعرفي، وتفاقم إقفار عضلة القلب أو قصور القلب لدى المرضى القلبيين.','Impaired cognitive/physical performance and exacerbation of angina or heart failure in patients with cardiovascular disease.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-i_sources_and_provenance','dis-iron-deficiency-anemia','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (3A00) · MedlinePlus NLM · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (3A00) · MedlinePlus NLM · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-iron-deficiency-anemia-j_terminology_and_links','dis-iron-deficiency-anemia','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','فقر الدم بعوز الحديد (Iron Deficiency Anemia) · الفيريتين (Ferritin) · الكريات الصغيرة ناقصة الصباغ (Microcytic Hypochromic).','Iron Deficiency Anemia · Serum Ferritin · Microcytic Hypochromic Erythrocytes.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-a_overview','dis-dvt','A_OVERVIEW','أ. نظرة عامة وتعريف موجز','A. Overview & Concise Definition','يمثل الخثار الوريدي العميق والانصمام الرئوي (PE) طيف الانصمام الخثري الوريدي (VTE).','Deep vein thrombosis and pulmonary embolism represent a continuum of venous thromboembolism (VTE).','GENERAL_EDUCATIONAL',1) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-b_epidemiology','dis-dvt','B_EPIDEMIOLOGY','ب. الانتشار وعوامل الخطورة والأسباب','B. Epidemiology, Etiology & Risk Factors','الركودة الوريدية (الرقاد المديد، الجراحة الكبرى)، أذية البطانة الوعائية، وفرط الخثورية الوراثي أو المكتسب.','Venous stasis (immobilization, major surgery), endothelial injury, and inherited or acquired hypercoagulability.','GENERAL_EDUCATIONAL',2) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-c_pathophysiology','dis-dvt','C_PATHOPHYSIOLOGY','ج. الفيزيولوجيا المرضية (كيف يحدث المرض؟)','C. Pathophysiology (Mechanism of Disease)','تجتمع عناصر ثلاثية فيرخوف (Virchow Triad: الركودة، أذية البطانة، فرط التخثر) لتفعيل شلال التخثر وتشكيل شبكة الفيبرين المتصالبة داخل جيوب الصمامات الوريدية العميقة.','Virchow triad (venous stasis, endothelial trauma, hypercoagulability) activates the coagulation cascade, generating cross-linked fibrin thrombi in deep venous valve pockets.','GENERAL_EDUCATIONAL',3) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-d_symptoms_red_flags','dis-dvt','D_SYMPTOMS_RED_FLAGS','د. الأعراض والعلامات التحذيرية (Red Flags)','D. Clinical Presentation & Red Flags','تورم أحادي الجانب في الساق، ألم، سخونة واحمرار. العلامات التحذيرية الطارئة للانصمام الرئوي (Red Flags): ضيق نفس حاد مفاجئ، ألم صدري جنبي، نفث دموي، تسرع قلب، أو غشي.','Unilateral leg swelling, warmth, tenderness. Red Flags for Pulmonary Embolism: sudden dyspnea, pleuritic chest pain, hemoptysis, tachycardia, or syncope.','CLINICAL_GUIDELINE_REF',4) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-e_diagnosis_differential','dis-dvt','E_DIAGNOSIS_DIFFERENTIAL','هـ. التقييم التشخيصي والتشخيص التفريقي','E. Diagnostic Workup & Differential Diagnosis','تقييم الاحتمال السريري (Wells Score)، معايرة D-dimer في الحالات منخفضة الاحتمال، والتصوير بالأمواج فوق الصوتية دوبلر للأوردة العميقة (Compression Ultrasonography).','Clinical pretest probability (Wells score), high-sensitivity D-dimer assay, and venous compression duplex ultrasonography.','CLINICAL_GUIDELINE_REF',5) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-f_non_pharmacological','dis-dvt','F_NON_PHARMACOLOGICAL','و. التدبير غير الدوائي ونمط الحياة','F. Non-Pharmacological & Lifestyle Management','التحريك المبكر بعد العمليات الجراحية، الجوارب الضاغطة المتدرجة عند الاستطباب، والإماهة الجيدة.','Early postoperative ambulation, mechanical prophylaxis, and hydration.','GENERAL_EDUCATIONAL',6) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-g_pharmacotherapy_classes','dis-dvt','G_PHARMACOTHERAPY_CLASSES','ز. الفئات الدوائية التعليمية المرتبطة (دون جرعات علاجية غير مراجعة)','G. Educational Pharmacotherapy Classes (No Unreviewed Clinical Dosing)','الفئات الدوائية التعليمية: 1) مضادات التخثر الفموية المباشرة المثبطة للعامل العاشر المفعل (Factor Xa Inhibitors) أو الثرومبين، 2) الهيبارينات منخفضة الوزن الجزيئي (LMWH)، 3) مضادات فيتامين K مع مراقبة INR.','Educational drug classes: 1) Direct Oral Anticoagulants (Factor Xa / Direct Thrombin Inhibitors), 2) Low-Molecular-Weight Heparins, 3) Vitamin K Antagonists.','UNDER_REVIEW_SAFEGUARD',7) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-h_complications_prognosis','dis-dvt','H_COMPLICATIONS_PROGNOSIS','ح. المتابعة والمضاعفات والإنذار','H. Monitoring, Complications & Prognosis','الانصمام الرئوي الحاد (Pulmonary Embolism) ومتلازمة ما بعد الخثار الوريدي المزمنة (Post-Thrombotic Syndrome).','Acute pulmonary embolism, chronic thromboembolic pulmonary hypertension, and post-thrombotic syndrome.','CLINICAL_GUIDELINE_REF',8) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-i_sources_and_provenance','dis-dvt','I_SOURCES_AND_PROVENANCE','ط. المصادر الموثوقة وتاريخ الاستيراد والمراجعة','I. Verified Sources, Import & Human Review Dates','المصادر: WHO ICD-11 (BD71) · NICE NG158 · NCBI StatPearls. تاريخ الاستيراد: 2026-10-22 · المراجعة البشرية: 2026-10-22.','Sources: WHO ICD-11 (BD71) · NICE NG158 · NCBI StatPearls. Imported: 2026-10-22 · Human Reviewed: 2026-10-22.','GENERAL_EDUCATIONAL',9) ON CONFLICT DO NOTHING;
INSERT INTO disease_sections (id,disease_id,section_code,title_ar,title_en,content_ar,content_en,information_tier,order_index) VALUES ('dis-dvt-j_terminology_and_links','dis-dvt','J_TERMINOLOGY_AND_LINKS','ي. المصطلحات العربية والإنجليزية والروابط التشريحية','J. Bilingual Terminology & Anatomical Links','الخثار الوريدي العميق (Deep Vein Thrombosis) · ثلاثية فيرخوف (Virchow Triad) · الانصمام الرئوي (Pulmonary Embolism).','Deep Vein Thrombosis (DVT) · Virchow Triad · Factor Xa Inhibition.','GENERAL_EDUCATIONAL',10) ON CONFLICT DO NOTHING;
